import sys
input = sys.stdin.read

def solve():
    data = input().split()

    b1 = int(data[0])
    q = int(data[1])
    l = int(data[2])
    m = int(data[3])

    bad_set = set(int(data[i]) for i in range(4, 4 + m))

    if abs(b1) > l:
        print(0)
        return

    if b1 == 0:
        if 0 in bad_set:
            print(0)
        else:
            print("inf")
        return

    if q == 0:
        if b1 in bad_set:
            if 0 in bad_set:
                print(0)
            else:
                print("inf")
        else:
            if 0 in bad_set:
                print(1)
            else:
                print("inf")
        return

    if q == 1:
        if b1 in bad_set:
            print(0)
        else:
            print("inf")
        return

    if q == -1:
        b1_bad = b1 in bad_set
        minus_b1_bad = (-b1) in bad_set
        if b1_bad and minus_b1_bad:
            print(0)
        else:
            print("inf")
        return

    count = 0
    current = b1
    while abs(current) <= l:
        if current not in bad_set:
            count += 1
        current *= q

    print(count)

solve()

